insert into products (legacy_id, slug, name, description, category, images, published) values
  (2, 'fauteuil-bubble-blanc', 'Fauteuil Bubble blanc', 'Le Fauteuil Bubble en version blanc immaculé — une silhouette sculpturale aux formes généreuses et organiques. Confort enveloppant, esthétique contemporaine, présence forte dans tout intérieur.', 'Salon', '["https://i.ibb.co/Fk1YZvkY/IMG-2568.jpg","https://i.ibb.co/NdBTdp4B/IMG-2567.jpg","https://i.ibb.co/tPsrFXWs/IMG-2566.jpg"]'::jsonb, false),
  (10, 'canape-bubble-blanc', 'Canapé Bubble blanc', 'Le Canapé Bubble 3 places en blanc crème immaculé — silhouette sculpturale et enveloppante, tissu bouclé doux au toucher. Une pièce maîtresse qui transforme instantanément votre salon.', 'Salon', '["https://i.ibb.co/wZRJYt6F/IMG-5364.jpg","https://i.ibb.co/mV8MC19X/IMG-2541.jpg","https://i.ibb.co/j9h5SNVC/IMG-2392.jpg"]'::jsonb, false),
  (6, 'fauteuil-bubble-bleu', 'Fauteuil Bubble bleu', 'Le Fauteuil Bubble dans un bleu Klein intense et vibrant — une déclaration artistique autant qu''une invitation au confort absolu. Texture unique en maille 3D structurée.', 'Salon', '["https://i.ibb.co/j941fSYQ/9-E1-B62-F9-998-D-4476-AE71-C8-C6-E2831-AC1.jpg","https://i.ibb.co/Z1HkzsfN/IMG-2553.jpg","https://i.ibb.co/x8LZvMgv/IMG-2565.jpg","https://i.ibb.co/rR0zYMWg/IMG-0932.jpg"]'::jsonb, false),
  (13, 'canape-bubble-bleu', 'Canapé Bubble bleu', 'Le Canapé Bubble 3 places en bleu Klein intense — une présence sculpturale et chromatique forte. Texture maille 3D signature, assise généreuse et enveloppante.', 'Salon', '["https://i.ibb.co/R1tJYDf/IMG-2491.jpg","https://i.ibb.co/tMbZ7D3Y/IMG-0586.jpg","https://i.ibb.co/QjXv6K98/IMG-0930.jpg"]'::jsonb, false),
  (8, 'fauteuil-bubble-rouge', 'Fauteuil Bubble rouge', 'Le Fauteuil Bubble dans un rouge vif et audacieux — énergie, caractère et confort sculptural réunis. Une pièce iconique qui s''impose dès le premier regard dans votre salon.', 'Salon', '["https://i.ibb.co/7Jc2Rvd8/IMG-5360.jpg","https://i.ibb.co/Cs8CPTX4/IMG-2558.jpg","https://i.ibb.co/5XbbZ7DH/IMG-2563.jpg"]'::jsonb, false),
  (22, 'canape-bubble-rouge', 'Canapé Bubble rouge', 'Le Canapé Bubble 3 places en rouge vif et ardent — énergie, caractère et confort sculptural. Une pièce iconique qui s''impose avec force dans votre espace de vie.', 'Salon', '["https://i.ibb.co/xSV6MBVx/47-B09888-A4-A8-44-E7-A80-D-7-E1-D7-BDDF6-ED.png","https://i.ibb.co/Kx5RnfCy/IMG-2542.jpg","https://i.ibb.co/99H4L0sP/IMG-2616.jpg"]'::jsonb, false),
  (12, 'canape-bubble-violet-special', 'Canapé Bubble violet spécial', 'Le Canapé Bubble 3 places dans un violet prune intense et vibrant — une édition spéciale aux proportions généreuses. Texture maille 3D unique, confort sculptural signature.', 'Salon', '["https://i.ibb.co/My8fK90B/IMG-2525.jpg","https://i.ibb.co/yBk1BSq4/IMG-2659.jpg","https://i.ibb.co/DfjGtFm8/IMG-2526.jpg","https://i.ibb.co/MksNPSck/IMG-2527.jpg"]'::jsonb, false),
  (7, 'fauteuil-bubble-vert', 'Fauteuil Bubble vert', 'Le Fauteuil Bubble dans un vert pistache lumineux — douceur organique et présence végétale. Même confort sculpturale signature, dans une teinte qui renouvelle l''intérieur.', 'Salon', '["https://i.ibb.co/0pnzSpFV/IMG-2557.jpg","https://i.ibb.co/nMm0vSZz/IMG-2552.jpg","https://i.ibb.co/99RwzY1n/IMG-2534.jpg"]'::jsonb, false),
  (9, 'fauteuil-bubble-orange', 'Fauteuil Bubble orange', 'Le Fauteuil Bubble dans un orange soleil audacieux — même silhouette sculpturale, même confort enveloppant, avec une couleur qui illumine instantanément votre intérieur.', 'Salon', '["https://i.ibb.co/xQ4XWSy/IMG-2530.jpg","https://i.ibb.co/mCyQ2HWm/IMG-2560.jpg","https://i.ibb.co/Jwd6qRVm/IMG-2559.jpg"]'::jsonb, false),
  (60, 'meuble-tv-bois-150-cm', 'Meuble TV bois 150 cm', 'Meuble TV contemporain en bois avec 2 tiroirs et niche ouverte. Façades cannelées, piètement métal noir incliné — un banc bas élégant qui structure votre salon, compatible TV jusqu''à 60 pouces.', 'Meubles', '["https://i.ibb.co/mr26F03b/Capture-d-e-cran-2026-07-23-a-12-11-20.png","https://i.ibb.co/cSvwJ9DP/Capture-d-e-cran-2026-07-23-a-12-10-23.png","https://i.ibb.co/jZ4hRQrZ/Capture-d-e-cran-2026-07-23-a-12-11-31.png","https://i.ibb.co/NdngcPKj/Capture-d-e-cran-2026-07-23-a-12-11-43.png","https://i.ibb.co/JRdmv4M3/Capture-d-e-cran-2026-07-23-a-12-12-46.png"]'::jsonb, false),
  (61, 'meuble-tv-extensible-noir', 'Meuble TV extensible noir', 'Meuble TV au design extensible (146 à 180 cm), en rotin avec 2 tiroirs, compartiments ouverts et rangement à 2 portes. Finition noir chêne élégante, parfait pour structurer un salon contemporain.', 'Meubles', '["https://i.ibb.co/PzVTnCtx/Capture-d-e-cran-2026-07-23-a-12-31-48.png","https://i.ibb.co/CKtMcfGs/Capture-d-e-cran-2026-07-23-a-12-31-56.png","https://i.ibb.co/NdNsLBF2/Capture-d-e-cran-2026-07-23-a-12-32-21.png","https://i.ibb.co/0WwS9zn/Capture-d-e-cran-2026-07-23-a-12-32-09.png"]'::jsonb, false),
  (62, 'table-a-manger-ovale-en-bois-massif', 'Table à manger ovale en bois massif', 'Table à manger moderne au design épuré, plateau ovale en bois massif et piètement cannelé. Chaleureuse et élégante, elle accueille jusqu''à 6 personnes. Disponible en Dark Brown et Light Brown.', 'Meubles', '["https://i.ibb.co/qMTxqsDx/Capture-d-e-cran-2026-07-23-a-14-36-33.png","https://i.ibb.co/WpP25YqM/Capture-d-e-cran-2026-07-23-a-14-36-15.png","https://i.ibb.co/XZ3vYFnR/Capture-d-e-cran-2026-07-23-a-14-36-08.png"]'::jsonb, false),
  (63, 'table-a-manger-ovale-en-bois-massif-63', 'Table à manger ovale en bois massif', 'Table à manger moderne au design épuré, plateau ovale en bois massif et piètement cannelé. Chaleureuse et élégante, elle accueille jusqu''à 6 personnes. Coloris Dark Brown, teinte chaude et profonde.', 'Meubles', '["https://i.ibb.co/B2VB3r8B/Capture-d-e-cran-2026-07-23-a-14-35-40.png","https://i.ibb.co/Q7mcpzGW/Capture-d-e-cran-2026-07-23-a-14-35-51.png","https://i.ibb.co/4gYLRVP0/Capture-d-e-cran-2026-07-23-a-14-35-48.png","https://i.ibb.co/1Js6RdH8/Capture-d-e-cran-2026-07-23-a-14-36-00.png"]'::jsonb, false),
  (64, 'meuble-tv-industriel-brun-rustique', 'Meuble TV industriel brun rustique', 'Banc TV de style industriel en brun rustique, pour téléviseur jusqu''à 55 pouces. Compartiments ouverts, étagère réglable et structure métal noir robuste. Idéal pour salon ou chambre.', 'Meubles', '["https://i.ibb.co/Pv2QZk4f/Capture-d-e-cran-2026-07-23-a-20-55-56.png","https://i.ibb.co/wrQbTCNM/Capture-d-e-cran-2026-07-23-a-20-55-45.png","https://i.ibb.co/p6rYtCdV/Capture-d-e-cran-2026-07-23-a-20-56-12.png"]'::jsonb, false),
  (71, 'vase-ceramique-coquille', 'Vase céramique coquille', 'Vase d''angle décoratif en céramique de style nordique, aux motifs inspirés du jardin et à la forme sculpturale de coquille. Fait main, blanc mat, il apporte une touche artistique et organique à votre intérieur.', 'Décorations', '["https://i.ibb.co/MXbJ1Ss/Capture-d-e-cran-2026-07-23-a-21-55-49.png","https://i.ibb.co/QjxsrSKs/Capture-d-e-cran-2026-07-23-a-21-56-06.png","https://i.ibb.co/DHsm1RcJ/Capture-d-e-cran-2026-07-23-a-21-56-21.png"]'::jsonb, false),
  (72, 'vase-ceramique-minimaliste', 'Vase céramique minimaliste', 'Vase en céramique au design moderne et minimaliste, forme sculpturale arrondie. Parfait pour un arrangement floral ou en pièce décorative seule dans le salon. Artisanat soigné, finition mate. Coloris Blanc.', 'Décorations', '["https://i.ibb.co/JwSGCFym/Capture-d-e-cran-2026-07-23-a-22-04-47.png","https://i.ibb.co/S4qCf5tR/Capture-d-e-cran-2026-07-23-a-22-04-15.png"]'::jsonb, false),
  (73, 'vase-ceramique-minimaliste-73', 'Vase céramique minimaliste', 'Vase en céramique au design moderne et minimaliste, forme sculpturale arrondie. Parfait pour un arrangement floral ou en pièce décorative seule dans le salon. Artisanat soigné, finition mate. Coloris Noir.', 'Décorations', '["https://i.ibb.co/cKJj0NkY/Capture-d-e-cran-2026-07-23-a-22-05-14.png","https://i.ibb.co/fV7ZZcWf/Capture-d-e-cran-2026-07-23-a-22-05-04.png"]'::jsonb, false),
  (74, 'commode-6-tiroirs-bois-noir', 'Commode 6 tiroirs bois & noir', 'Commode moderne à 6 tiroirs, unité de rangement idéale pour la chambre ou l''entrée. Structure noire et façades bois chocolat, en MDF durable. Grande capacité pour vêtements et essentiels, style contemporain.', 'Meubles', '["https://i.ibb.co/cSH9XcdH/Capture-d-e-cran-2026-07-23-a-22-23-19.png","https://i.ibb.co/kWbJVR5/Capture-d-e-cran-2026-07-23-a-22-21-45.png","https://i.ibb.co/bg1YMfM9/Capture-d-e-cran-2026-07-23-a-22-23-11.png","https://i.ibb.co/Mxf3wGjT/Capture-d-e-cran-2026-07-23-a-22-23-03.png","https://i.ibb.co/DHp15LLC/Capture-d-e-cran-2026-07-23-a-22-22-03.png"]'::jsonb, false),
  (75, 'commode-meuble-tv-long-a-tiroirs', 'Commode meuble TV long à tiroirs', 'Commode multifonction et meuble TV long, avec étagère de rangement ouverte et tiroirs en tissu. Sur roulettes pour un déplacement facile. Unité de rangement polyvalente pour la chambre comme pour le salon.', 'Meubles', '["https://i.ibb.co/dwT4Jdkt/Capture-d-e-cran-2026-07-28-a-17-06-39.png","https://i.ibb.co/QF9bT2B6/Capture-d-e-cran-2026-07-28-a-17-06-56.png","https://i.ibb.co/dwQYzJc7/Capture-d-e-cran-2026-07-28-a-17-06-48.png","https://i.ibb.co/ZpbfLsNS/Capture-d-e-cran-2026-07-28-a-17-07-42.png","https://i.ibb.co/DHTCpCs4/Capture-d-e-cran-2026-07-28-a-17-07-30.png"]'::jsonb, false),
  (76, 'commode-blanche-6-tiroirs', 'Commode blanche 6 tiroirs', 'Commode de rangement moderne à 6 tiroirs, en blanc épuré. Grande capacité pour la chambre, le salon ou un couloir. Lignes minimalistes et finition soignée qui s''accordent à tous les intérieurs.', 'Meubles', '["https://i.ibb.co/xK73wXnm/Capture-d-e-cran-2026-08-02-a-14-26-49.png","https://i.ibb.co/QjKfjjHr/Capture-d-e-cran-2026-08-02-a-14-27-14.png","https://i.ibb.co/DPSMdRnk/Capture-d-e-cran-2026-08-02-a-14-27-22.png","https://i.ibb.co/F2Sb5GL/Capture-d-e-cran-2026-08-02-a-14-26-59.png"]'::jsonb, false),
  (112, 'canape-sectionnel-convertible-3-places-gris', 'Canapé sectionnel convertible 3 places gris', 'Grand canapé sectionnel convertible 3 places en velours côtelé gris, sans armature apparente. Assise profonde et enveloppante, coussins moelleux inclus. Modulable et personnalisable selon votre espace, il se transforme en couchage d''appoint — un choix parfait pour un salon cosy et contemporain.', 'Salon', '["https://i.ibb.co/0pLxdQnx/Capture-d-e-cran-2026-08-22-a-12-52-18.png","https://i.ibb.co/sdDj8LRX/Capture-d-e-cran-2026-08-22-a-12-52-31.png","https://i.ibb.co/zhTmJSDw/Capture-d-e-cran-2026-08-22-a-12-52-48.png","https://i.ibb.co/QFmhnQWJ/Capture-d-e-cran-2026-08-22-a-12-52-56.png"]'::jsonb, false),
  (113, 'canape-modulable-en-u-style-nuage-blanc', 'Canapé modulable en U style nuage blanc', 'Grand canapé modulable en forme de U, style nuage, revêtu d''un velours doux et enveloppant. Sans armature apparente, assise profonde et généreuse, modules déplaçables selon votre espace. Coloris blanc lumineux et élégant — un salon cosy et contemporain.', 'Salon', '["https://i.ibb.co/MDdS1P5n/Capture-d-e-cran-2026-08-22-a-13-02-52.png"]'::jsonb, false),
  (114, 'canape-modulable-en-u-style-nuage-noir', 'Canapé modulable en U style nuage noir', 'Grand canapé modulable en forme de U, style nuage, revêtu d''un velours doux et enveloppant. Sans armature apparente, assise profonde et généreuse, modules déplaçables selon votre espace. Coloris noir profond et raffiné — un salon cosy et contemporain.', 'Salon', '["https://i.ibb.co/ZRzPhJHk/Capture-d-e-cran-2026-08-22-a-13-02-45.png","https://i.ibb.co/bjMYp00z/Capture-d-e-cran-2026-08-22-a-13-03-21.png","https://i.ibb.co/m5hRKxpr/Capture-d-e-cran-2026-08-22-a-13-03-30.png","https://i.ibb.co/0yBwH7M9/Capture-d-e-cran-2026-08-22-a-13-03-12.png","https://i.ibb.co/PZ8DHPdH/Capture-d-e-cran-2026-08-22-a-13-03-03.png","https://i.ibb.co/7t2k9k0y/Capture-d-e-cran-2026-08-22-a-13-03-40.png"]'::jsonb, false),
  (115, 'canape-modulable-en-u-style-nuage-gris', 'Canapé modulable en U style nuage gris', 'Grand canapé modulable en forme de U, style nuage, revêtu d''un velours doux et enveloppant. Sans armature apparente, assise profonde et généreuse, modules déplaçables selon votre espace. Coloris gris élégant et intemporel — un salon cosy et contemporain.', 'Salon', '["https://i.ibb.co/bgBW2csJ/Capture-d-e-cran-2026-08-22-a-13-02-29.png"]'::jsonb, false),
